def gen(rng):
    letters = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789'
    vowels = 'aeiouAEIOU'
    def sentence(n, vp):
        out = []
        for i in range(n):
            r = rng.random()
            if r < 0.15 and 0 < i < n - 1:
                out.append(' ')
            elif r < 0.2 and 0 < i < n - 1:
                out.append(rng.choice('.,!?'))
            elif rng.random() < vp:
                out.append(rng.choice(vowels))
            else:
                out.append(rng.choice(letters))
        s = ''.join(out).strip()
        if not any(c in vowels for c in s):
            s = 'a' + s[1:] if len(s) > 1 else 'a'
        return s
    tests = ['a', 'E', 'Hello World', 'rhythm and blues', 'AEIOU xyz', 'xyz u', 'aaa bbb', 'a b', 'Why? Yes, Y is not a vowel.']
    for n in (3, 5, 8, 12, 20, 40, 80):
        for _ in range(3):
            tests.append(sentence(n, rng.choice([0.1, 0.4, 0.8])))
    tests.append(sentence(100000, 0.4))
    tests.append('a' * 100000)
    tests.append(sentence(100000, 0.05))
    return tests

